/**
 * Writes full sdk `Market` records from @strata/config (generated by scripts/fetch-markets.ts from a
 * live Indexer query) into markets.data, so readers get symbol, tick sizes and arena limits.
 * `arena_enabled` stays owned by the arena poller (MarketSet events) and is not touched.
 */
import { markets, type Db } from "@strata/db";
import { Market } from "@strata/sdk";
import { sql } from "drizzle-orm";

export async function upsertMarketCatalog(db: Db, catalog: readonly unknown[]): Promise<{ written: number; invalid: number }> {
  const rows = [];
  let invalid = 0;
  for (const raw of catalog) {
    const r = Market.safeParse(raw);
    if (!r.success) {
      invalid += 1;
      continue;
    }
    const m = r.data;
    rows.push({ network: m.network, marketId: m.marketId.toLowerCase(), ticker: m.ticker, data: m, fetchedAt: new Date(m.fetchedAt) });
  }
  for (let i = 0; i < rows.length; i += 200) {
    await db
      .insert(markets)
      .values(rows.slice(i, i + 200))
      .onConflictDoUpdate({
        target: [markets.network, markets.marketId],
        set: { ticker: sql`excluded.ticker`, data: sql`excluded.data`, fetchedAt: sql`excluded.fetched_at` },
      });
  }
  return { written: rows.length, invalid };
}
